    """Test that remap can ignore lists entirely without visiting their contents."""
    data = {
        "thing1": "",
        "thing2": None,
        "thing3": ["", None]
    }

    def drop_empty_and_none(path, key, value) -> bool:
        # Return False for empty strings and None to filter them out
        return value not in ["", None]

