from boltons.funcutils import wraps


def test_wraps_add_parameters():
    """Test that wraps() can add parameters to a wrapped function."""

    def add_arg_extra_arg(func):
        @wraps(func)
        def wrapper(*args, extra_arg=None, **kwargs):
            if extra_arg is not None:
                wrapper.extra_arg_value = extra_arg
            return func(*args, **kwargs)
        return wrapper

    @add_arg_extra_arg
    def myfunc(arg1, arg2, arg3='default'):
        return f"arg1={arg1}, arg2={arg2}, arg3={arg3}"

    # Test that the wrapped function accepts the extra_arg parameter
    result = myfunc('val1', 'val2', extra_arg='extra!')
    assert result == "arg1=val1, arg2=val2, arg3=default"
    assert myfunc.extra_arg_value == 'extra!'

    # Test that the signature includes the extra_arg parameter
    import inspect
    sig = inspect.signature(myfunc)
    assert 'extra_arg' in sig.parameters

    # Test that original parameters still work
    result2 = myfunc('val1', 'val2', arg3='custom')
    assert result2 == "arg1=val1, arg2=val2, arg3=custom"

