    properties = fields.Nested(PropertySchema, many=True, required=False)


class TrackInteractionActionSchemaNew(marshmallow.Schema):
    properties = fields.List(fields.Nested(PropertySchema), required=False)


def test_nested_many_vs_list_performance():
    """Test that Nested with many=True has comparable performance to List of Nested"""
    data = {
        "properties": [
            {"name": "x0", "value": "v"} for x in range(20000)
        ]
    }

    def load_nested_many():
        schema = TrackInteractionActionSchema()
        try:
            schema.load(data)
        except validate.ValidationError:
            pass

    def load_list_nested():
        schema = TrackInteractionActionSchemaNew()
        try:
            schema.load(data)
        except validate.ValidationError:
            pass

    time_nested_many = timeit.timeit(load_nested_many, number=3)
    time_list_nested = timeit.timeit(load_list_nested, number=3)

    # Nested with many=True should not be significantly slower than List of Nested
    # Allow up to 1.5x slower (performance regression threshold)
    assert time_nested_many < time_list_nested * 1.5, \
        f"Nested(many=True) is too slow: {time_nested_many:.3f}s vs List: {time_list_nested:.3f}s"

