def test_doubly_nested_schemas_with_instantiated_lambda_and_dot_notation():
    """Test that doubly nested schemas instantiated via lambdas work with dot notation in only parameter."""

    class ASchema(Schema):
        a = fields.String()
        a2 = fields.String()

    class BSchema(Schema):
        b = fields.Nested(lambda: ASchema)

    class CSchema(Schema):
        c = fields.Nested(lambda: BSchema())  # Instantiated lambda

    class DSchema(Schema):
        d = fields.Nested(lambda: CSchema, only=("c.b.a2",))

    class A:
        def __init__(self):
            self.a = 'Hello from a'
            self.a2 = 'Hello from a2'

    class B:
        def __init__(self, a):
            self.b = a

    class C:
        def __init__(self, b):
            self.c = b

    class D:
        def __init__(self, c):
            self.d = c

    result = DSchema().dump(D(C(B(A()))))

    # The output should contain the nested a2 field, not be empty
    assert result == {'d': {'c': {'b': {'a2': 'Hello from a2'}}}}
    # Ensure it's not the buggy output
    assert result != {'d': {'c': {}}}

