class MarshModel:
    """Base class for ORM-style models with marshmallow integration"""

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        # Create schema from class annotations and fields
        schema_attrs = {}
        for key, value in cls.__dict__.items():
            if isinstance(value, fields.Field):
                schema_attrs[key] = value

        # Create schema class dynamically
        schema_class = type(f'{cls.__name__}Schema', (Schema,), schema_attrs)

        # Handle meta_args if defined
        if hasattr(cls, '__meta_args__'):
            meta_attrs = {'unknown': cls.__meta_args__.get('unknown', INCLUDE)}
            schema_class.Meta = type('Meta', (), meta_attrs)

        cls.__schema__ = schema_class()

    @classmethod
    def load(cls, data):
        """Load data and return instance"""
        validated_data = cls.__schema__.load(data)
        return cls(**validated_data)

    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    def dump(self):
        """Serialize instance to dict"""
        data = {}
        for key in self.__schema__.fields:
            if hasattr(self, key):
                data[key] = getattr(self, key)
        return self.__schema__.dump(data)


