from typing import Iterable


class Interval:
    """A custom class that is not iterable but supports __and__"""

    def __init__(self, start, end):
        self.start = start
        self.end = end

    def __contains__(self, value):
        return self.start <= value <= self.end

    def __and__(self, other):
        if isinstance(other, Interval):
            return Interval(max(self.start, other.start), min(self.end, other.end))
        elif isinstance(other, Iterable):
            return {x for x in other if x in self}
        else:
            return NotImplemented


def test_sorted_set_and_returns_not_implemented_for_unsupported_type():
    """Test that SortedSet.__and__ returns NotImplemented for unsupported types"""
    sorted_set = SortedSet([1, 2, 3, 4, 5])
    interval = Interval(2, 4)

    # This should not raise TypeError
    # Instead, it should allow interval.__and__(sorted_set) to be called
    result = sorted_set & interval

    # The result should be a set containing elements in both sorted_set and interval
    assert result == {2, 3, 4}

