from math import ceil
from tlz import merge, partition_all


def chunk_dict(n: int, d: dict):
    """Chunk a dict of lists into separate dicts with lists of max length `n`."""
    def chunk(k, v):
        if hasattr(v, '__len__') and hasattr(v, '__getitem__'):
            try:
                return ({k: v[i*n:(i+1)*n]} for i in range(ceil(len(v)/n)))
            except:
                pass
        return ({k: part} for part in partition_all(n, v))
    return list(map(merge, zip_longest(*starmap(chunk, d.items()), fillvalue={})))


def test_chunk_dict_basic():
    """Test chunking a dictionary with list values"""
    d = {'a': [1, 3, 5], 'b': [2, 4, 6]}
    result = chunk_dict(2, d)

    assert len(result) == 2
    assert result[0] == {'a': [1, 3], 'b': [2, 4]}
    assert result[1] == {'a': [5], 'b': [6]}


def test_chunk_dict_with_numpy_arrays():
    """Test chunking a dictionary with numpy array values"""
    try:
        import numpy as np
    except ImportError:
        pytest.skip("numpy not installed")

    d = {'a': np.array([1, 2, 3, 7]), 'b': np.array([4, 5, 6, 8])}
    result = chunk_dict(2, d)

    assert len(result) == 2
    assert np.array_equal(result[0]['a'], np.array([1, 2]))
    assert np.array_equal(result[0]['b'], np.array([4, 5]))
    assert np.array_equal(result[1]['a'], np.array([3, 7]))
    assert np.array_equal(result[1]['b'], np.array([6, 8]))

